const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
  const cambodia = countries.filter(ee.Filter.eq('country_na', 'Cambodia')).geometry();
  const vietnam = countries.filter(ee.Filter.eq('country_na', 'Vietnam')).geometry();

  const startDate = '2016-08-01';
  const endDate = '2018-02-28';

  // 2. Data Acquisition - MODIS Fire Product
  let fireCol = ee.ImageCollection('MODIS/061/MCD14ML')
    .filterDate(startDate, endDate);

  const colSize = fireCol.size().getInfo();
  console.log(`Total fire collection size: ${colSize}`);

  if (colSize === 0) {
    console.log("No fire data found for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Count fire detections for each country
  // MCD14ML has MaxFRP band - we'll count pixels with fire detections
  const fireImage = fireCol.select(['MaxFRP']).max(); // Get maximum FRP across all dates

  // Count fire pixels in Cambodia
  const cambodiaStats = fireImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cambodia,
    scale: 1000,
    maxPixels: 1e9
  });

  const cambodiaCount = cambodiaStats.get('MaxFRP').getInfo();

  // Count fire pixels in Vietnam
  const vietnamStats = fireImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: vietnam,
    scale: 1000,
    maxPixels: 1e9
  });

  const vietnamCount = vietnamStats.get('MaxFRP').getInfo();

  console.log(`Cambodia fire detections: ${cambodiaCount}`);
  console.log(`Vietnam fire detections: ${vietnamCount}`);

  // 4. Validation & Final Answer
  if (cambodiaCount === null || vietnamCount === null) {
    console.log("Calculation failed - null values returned.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (cambodiaCount === 0 && vietnamCount === 0) {
    console.log("No valid fire pixels detected in either country.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Compare and answer
  if (cambodiaCount > vietnamCount) {
    console.log("Cambodia had MORE active fire detections than Vietnam.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Cambodia did NOT have more active fire detections than Vietnam.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
